package server

const loginJS = `const boxes=[...document.querySelectorAll('.otp')],hidden=document.getElementById('totp');
function sync(){hidden.value=boxes.map(x=>x.value.replace(/\D/g,'')).join('')}
boxes.forEach((b,i)=>{b.addEventListener('input',()=>{b.value=b.value.replace(/\D/g,'').slice(0,1);sync();if(b.value&&i<5)boxes[i+1].focus()});b.addEventListener('keydown',e=>{if(e.key==='Backspace'&&!b.value&&i>0)boxes[i-1].focus()});b.addEventListener('paste',e=>{const t=(e.clipboardData||window.clipboardData).getData('text').replace(/\D/g,'').slice(0,6);if(t.length){e.preventDefault();[...t].forEach((c,j)=>{if(boxes[j])boxes[j].value=c});sync();boxes[Math.min(t.length,6)-1].focus()}})});document.getElementById('loginForm')?.addEventListener('submit',sync);`

const appJS = `const clock=document.getElementById('clock');function tick(){if(clock)clock.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Hong_Kong',weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())+' HKT'}tick();setInterval(tick,1000);
const drawer=document.getElementById('flowDrawer');const overlay=document.getElementById('drawerOverlay');function closeDrawer(){drawer?.classList.remove('open');overlay?.classList.remove('open')}document.getElementById('closeDrawer')?.addEventListener('click',closeDrawer);overlay?.addEventListener('click',closeDrawer);document.querySelectorAll('[data-flow]').forEach(row=>row.addEventListener('click',e=>{if(e.target.closest('a,button,input,select'))return;const d=row.dataset;for(const k of ['time','user','device','source','resource','destination','protocol','traffic','packets','status']){const el=document.getElementById('fd-'+k);if(el)el.textContent=d[k]||'-'}drawer?.classList.add('open');overlay?.classList.add('open')}));
const search=document.getElementById('globalSearch');if(search){search.addEventListener('keydown',e=>{if(e.key==='Enter'){location.href='/access-logs?q='+encodeURIComponent(search.value)}})};`

const loginPage = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NetBird Audit — Sign In</title><style>
:root{color-scheme:dark;--bg:#06111f;--panel:#0b1728;--line:#21324a;--text:#f4f7fb;--muted:#93a4ba;--blue:#3b82f6;--green:#34d399}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:radial-gradient(circle at 28% 40%,#0e2f59 0,#07182c 28%,#050d18 68%);color:var(--text);min-height:100vh}.shell{min-height:100vh;display:grid;grid-template-columns:minmax(0,1.55fr) minmax(460px,.95fr)}.hero{position:relative;overflow:hidden;padding:48px 6vw 36px;border-right:1px solid #14253b}.hero:before{content:"";position:absolute;width:760px;height:760px;border-radius:50%;right:-150px;top:75px;background:radial-gradient(circle at 38% 40%,#1b5fb36e 0 2px,transparent 3px),radial-gradient(circle at 60% 46%,#2f83ff99 0 3px,transparent 4px),radial-gradient(circle at 55% 50%,transparent 0 43%,#1f62a955 43.2%,transparent 43.8%),radial-gradient(circle,#0a2a4d,#071a31 48%,#03101d 71%);box-shadow:0 0 100px #1263cf27 inset,0 0 80px #0b63ce1f}.hero:after{content:"";position:absolute;inset:0;background-image:linear-gradient(#ffffff05 1px,transparent 1px),linear-gradient(90deg,#ffffff05 1px,transparent 1px);background-size:52px 52px;mask-image:linear-gradient(to right,black,transparent 80%)}.brand,.copy,.feature-list,.quote,.foot{position:relative;z-index:2}.brand{display:flex;align-items:center;gap:14px;font-size:28px;font-weight:760}.shield{width:48px;height:55px;display:grid;place-items:center;clip-path:polygon(50% 0,92% 15%,84% 72%,50% 100%,16% 72%,8% 15%);background:linear-gradient(145deg,#4c91ff,#1762e8)}.shield:after{content:"✦";font-size:23px}.subbrand{font-size:16px;font-weight:500;color:#b9c6d8;margin-top:2px}.eyebrow{letter-spacing:.42em;color:#7e94b1;font-size:12px;margin:18px 0 42px}.copy{max-width:620px;margin-top:30px}.copy h1{font-size:54px;line-height:1.05;margin:0 0 20px;letter-spacing:-.035em}.copy h1 span{color:#4d8eff}.copy p{font-size:19px;line-height:1.6;color:#b1bed0}.feature-list{display:grid;gap:20px;margin-top:32px;width:390px}.feature{display:grid;grid-template-columns:48px 1fr;gap:14px;align-items:center}.ico{width:48px;height:48px;border-radius:12px;background:#0d2746;border:1px solid #1c426c;display:grid;place-items:center;color:#6aa6ff}.feature b{display:block}.feature small{color:#93a5bb}.quote{margin-top:38px;width:390px;border:1px solid #1b3556;background:#0a1a2cca;border-radius:12px;padding:18px 20px;color:#aebdd0}.foot{position:absolute;left:6vw;bottom:28px;color:#667c99;font-size:12px}.login-side{background:linear-gradient(180deg,#081523,#06101b);display:grid;place-items:center;padding:48px}.card{width:min(100%,460px);padding:40px 34px;border:1px solid #20344f;border-radius:20px;background:linear-gradient(180deg,#101d2eeb,#0b1727ee);box-shadow:0 28px 100px #0007}.logo{text-align:center}.logo .shield{margin:0 auto 14px}.logo h2{font-size:29px;margin:0 0 5px}.desc{color:#9baac0}.field{margin-top:20px}.field label{display:block;font-size:14px;margin-bottom:8px}.input{width:100%;height:52px;padding:0 15px;border-radius:10px;border:1px solid #2a3d57;background:#0c1929;color:#f7f9fc;font-size:15px}.otp-wrap{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;width:100%;max-width:100%;overflow:hidden}.otp{width:100%;min-width:0;max-width:100%;height:52px;padding:0;text-align:center;font-size:20px;font-weight:700;border-radius:10px;border:1px solid #2b405c;background:#0b1828;color:#fff;box-sizing:border-box;outline:none}.otp:focus{border-color:#3b82f6;box-shadow:0 0 0 3px #2563eb26}.btn{width:100%;height:54px;border:0;border-radius:10px;background:linear-gradient(90deg,#2167ed,#3d8cff);color:white;font-weight:700;font-size:16px;cursor:pointer;margin-top:22px}.security{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:28px;padding-top:22px;border-top:1px solid #1d2f46;color:#7f91a9;font-size:11px;text-align:center}.security strong{display:block;color:#b6c4d6;margin-top:5px}.ver{text-align:right;color:#536b89;font-size:11px;margin-top:16px}@media(max-width:1100px){.shell{grid-template-columns:minmax(0,1.25fr) minmax(420px,.95fr)}.copy h1{font-size:46px}}@media(max-width:980px){.shell{grid-template-columns:1fr}.hero{display:none}.login-side{min-height:100vh;padding:24px}.card{width:min(100%,460px)}}@media(max-width:520px){.login-side{padding:16px}.card{padding:28px 20px;border-radius:16px}.otp-wrap{gap:6px}.otp{height:48px;font-size:18px}.security{grid-template-columns:1fr;gap:8px}}
</style></head><body><div class="shell"><section class="hero"><div class="brand"><div class="shield"></div><div>NetBird Audit<div class="subbrand">Gateway V3.4</div></div></div><div class="eyebrow">SEE · AUDIT · PROTECT</div><div class="copy"><h1>Turn Your Private Network into an <span>Auditable, Secure Environment.</span></h1><p>Monitor, audit and analyze NetBird access to internal resources with clear identity, session and flow visibility.</p></div><div class="feature-list"><div class="feature"><div class="ico">◉</div><div><b>Real-time Visibility</b><small>See who accessed what, when and from where.</small></div></div><div class="feature"><div class="ico">▥</div><div><b>eBPF Powered</b><small>Low-overhead flow auditing on the routing peer.</small></div></div><div class="feature"><div class="ico">◆</div><div><b>Built for Security</b><small>Independent audit plane with MFA and TLS.</small></div></div></div><div class="quote">“Better visibility. A safer infrastructure. A more productive team.”</div><div class="foot">NetBird Audit Gateway V3.4 · Go + eBPF · MySQL</div></section><section class="login-side"><form class="card" method="post" id="loginForm"><div class="logo"><div class="shield"></div><h2>NetBird Audit</h2><div class="desc">Gateway V3.4.1 · Welcome back</div></div><div class="field"><label>Username</label><input class="input" name="username" autocomplete="username" placeholder="auditadmin" required></div><div class="field"><label>Password</label><input class="input" name="password" type="password" autocomplete="current-password" placeholder="••••••••••••" required></div><div class="field"><label>Authenticator Code</label><div class="otp-wrap"><input class="otp" inputmode="numeric" maxlength="1"><input class="otp" inputmode="numeric" maxlength="1"><input class="otp" inputmode="numeric" maxlength="1"><input class="otp" inputmode="numeric" maxlength="1"><input class="otp" inputmode="numeric" maxlength="1"><input class="otp" inputmode="numeric" maxlength="1"></div><input type="hidden" name="totp" id="totp" required></div><button class="btn" type="submit">Sign In →</button><div class="security"><div>🔒<strong>Encrypted</strong></div><div>◆<strong>MFA Protected</strong></div><div>▤<strong>Audit Ready</strong></div></div><div class="ver">v3.4.1</div></form></section></div><script src="/assets/login.js" defer></script></body></html>`

const pageTemplate = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Title}} — NetBird Audit</title><style>
:root{color-scheme:dark;--bg:#07111d;--panel:#0d1927;--panel2:#101e2e;--line:#203048;--text:#f4f7fb;--muted:#8da0b8;--blue:#3485ff;--green:#31d182;--red:#ff6474;--purple:#9b6bff;--cyan:#2dd4bf}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 55% -10%,#112941 0,#07111d 42%,#050d17 100%);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.app{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;border-right:1px solid #17263a;background:#07111eea;padding:24px 14px;display:flex;flex-direction:column}.brand{display:flex;gap:10px;align-items:center;font-weight:780;font-size:18px;padding:0 8px 24px}.shield{width:35px;height:40px;clip-path:polygon(50% 0,92% 15%,84% 72%,50% 100%,16% 72%,8% 15%);background:linear-gradient(145deg,#4c91ff,#1762e8);display:grid;place-items:center}.shield:after{content:"✦"}.version{display:block;color:#7790ae;font-size:10px;font-weight:500;margin-top:2px}.nav{display:grid;gap:7px}.nav a{display:flex;gap:11px;align-items:center;color:#c1cce0;text-decoration:none;padding:11px 12px;border-radius:9px;font-size:14px}.nav a:hover,.nav a.active{background:linear-gradient(90deg,#173e77,#1955ad);color:#fff}.nav .ico{width:18px;color:#8facd1}.sidebar-foot{margin-top:auto;color:#7890aa;font-size:11px;display:grid;gap:10px;padding:8px}.main{min-width:0;padding:28px 32px 44px}.topbar{display:flex;justify-content:space-between;gap:22px;align-items:flex-start;margin-bottom:22px}.topbar h1{font-size:26px;margin:0 0 5px;letter-spacing:-.02em}.topbar p{margin:0;color:#93a5bc}.actions{display:flex;align-items:center;gap:10px}.search{width:330px;height:40px;border:1px solid #22344b;background:#0a1625;border-radius:9px;color:#dce6f4;padding:0 13px}.clock,.user,.btn,.select,.input{border:1px solid #22344b;background:#0b1726;color:#dce6f4;border-radius:9px}.clock,.user{padding:10px 12px;font-size:13px}.btn{padding:10px 14px;text-decoration:none;cursor:pointer;font-weight:650}.btn.primary{background:linear-gradient(90deg,#246de8,#3188ff);border-color:#347fff;color:white}.btn.danger{color:#ff9aaa}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}.card{background:linear-gradient(180deg,#0e1a29,#0b1624);border:1px solid #1d2d42;border-radius:12px;box-shadow:0 12px 36px #0002}.metric{padding:18px}.metric .label{color:#bec9d9;font-size:13px}.metric .num{font-size:29px;font-weight:780;margin:13px 0 3px}.metric .hint{color:#7187a4;font-size:12px}.green{color:var(--green)}.red{color:var(--red)}.blue{color:#5ba0ff}.layout{display:grid;grid-template-columns:1.7fr .9fr;gap:14px}.section{padding:16px;margin-bottom:14px}.section-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.section h2{font-size:16px;margin:0}.muted{color:var(--muted)}.chart{height:190px;display:flex;align-items:flex-end;gap:5px;padding:18px 4px 3px;border-bottom:1px solid #1c2b40}.bar{flex:1;min-width:6px;background:linear-gradient(180deg,#328aff,#163e79);border-radius:3px 3px 0 0}.top-resource{display:grid;grid-template-columns:1fr auto;gap:8px;padding:10px 0;border-bottom:1px solid #18263a}.filters{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:14px}.select,.input{height:40px;padding:0 12px}.input{min-width:260px}.table-wrap{overflow:auto;border:1px solid #1b2a3e;border-radius:10px}.table{width:100%;border-collapse:collapse;min-width:900px}.table th{color:#8fa3bd;text-align:left;font-size:11px;font-weight:650;padding:11px 12px;border-bottom:1px solid #1c2b40;background:#0a1624;white-space:nowrap}.table td{font-size:12px;padding:11px 12px;border-bottom:1px solid #172638;white-space:nowrap}.table tr:last-child td{border-bottom:0}.table tbody tr{cursor:pointer}.table tbody tr:hover{background:#102037}.badge{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 9px;font-size:11px}.badge.green{background:#0c3a29;color:#55e7a1}.badge.blue{background:#102e5b;color:#6cadff}.badge.gray{background:#172435;color:#98aabd}.badge.red{background:#431d28;color:#ff8998}.dot{width:7px;height:7px;border-radius:50%;background:currentColor}.empty{padding:48px;text-align:center;color:#7187a4}.resource-row{display:grid;grid-template-columns:minmax(160px,1.2fr) minmax(160px,1fr) minmax(140px,.9fr) 120px minmax(260px,1.4fr);gap:12px;align-items:center;padding:13px;border-bottom:1px solid #1b2b40}.resource-row:last-child{border-bottom:0}.resource-name b{display:block}.resource-name small{color:#7890aa}.inline-form{display:flex;gap:7px;align-items:center}.inline-form .select,.inline-form .input{height:34px;min-width:0}.inline-form .input{width:105px}.health-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.health{padding:20px;display:flex;justify-content:space-between;align-items:center}.drawer-overlay{position:fixed;inset:0;background:#0007;display:none;z-index:20}.drawer-overlay.open{display:block}.drawer{position:fixed;top:0;right:-440px;width:420px;max-width:92vw;height:100vh;background:#0b1624;border-left:1px solid #23364e;z-index:30;transition:.22s;padding:24px;box-shadow:-30px 0 80px #0007}.drawer.open{right:0}.drawer-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #1c2d42;padding-bottom:16px}.drawer dl{display:grid;grid-template-columns:120px 1fr;gap:12px;margin-top:22px}.drawer dt{color:#7f93ad}.drawer dd{margin:0}.close{border:0;background:transparent;color:#9db0c8;font-size:22px;cursor:pointer}.row-actions{display:flex;gap:8px}.statusline{display:flex;align-items:center;gap:8px}.notice{padding:12px 14px;border-radius:9px;background:#10213a;border:1px solid #24446f;color:#a9c9f6;margin-bottom:14px}.unsupported{color:#ffba55;font-size:11px}@media(max-width:1100px){.grid4{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}.actions .search{display:none}.resource-row{grid-template-columns:1fr 1fr}.health-grid{grid-template-columns:1fr}}@media(max-width:760px){.app{grid-template-columns:1fr}.sidebar{position:relative;height:auto}.main{padding:20px}.grid4{grid-template-columns:1fr}.topbar{flex-direction:column}.nav{grid-template-columns:repeat(2,1fr)}}
</style></head><body><div class="app"><aside class="sidebar"><div class="brand"><div class="shield"></div><div>NetBird Audit<span class="version">Gateway V3.4</span></div></div><nav class="nav"><a class="{{if eq .Page "overview"}}active{{end}}" href="/"><span class="ico">⌂</span>Overview</a><a class="{{if eq .Page "logs"}}active{{end}}" href="/access-logs"><span class="ico">▣</span>Access Logs</a><a class="{{if eq .Page "sessions"}}active{{end}}" href="/vpn-sessions"><span class="ico">◉</span>VPN Sessions</a><a class="{{if eq .Page "resources"}}active{{end}}" href="/resources"><span class="ico">▤</span>Resources</a><a class="{{if eq .Page "peers"}}active{{end}}" href="/peers"><span class="ico">♧</span>Peers</a><a class="{{if eq .Page "health"}}active{{end}}" href="/system-health"><span class="ico">⚙</span>System Health</a></nav><div class="sidebar-foot"><div><span class="green">●</span> Audit System Online</div><div>v3.4.0</div><div>◷ Asia/Hong_Kong</div></div></aside><main class="main"><header class="topbar"><div><h1>{{.Title}}</h1><p>{{.Subtitle}}</p></div><div class="actions"><input id="globalSearch" class="search" placeholder="Search users, IPs, resources, devices..."><div id="clock" class="clock">HKT</div><div class="user">● {{.AdminUser}}</div><a class="btn" href="/logout">Logout</a></div></header>
{{if eq .Page "overview"}}<div class="grid4"><div class="card metric"><div class="label">Online Peers</div><div class="num">{{.Online}}</div><div class="hint"><span class="green">●</span> of {{.Peers}} known peers</div></div><div class="card metric"><div class="label">VPN Sessions · 24h</div><div class="num">{{.Sessions}}</div><div class="hint">identity sessions observed</div></div><div class="card metric"><div class="label">Access Logs · 24h</div><div class="num">{{.Flows}}</div><div class="hint">audited resource flows</div></div><div class="card metric"><div class="label">Security Alerts · 24h</div><div class="num">{{.Alerts}}</div><div class="hint">failed console logins</div></div></div><div class="layout"><section class="card section"><div class="section-head"><h2>Traffic Overview · Last 24h</h2><span class="muted">flows per hour</span></div>{{if .Hourly}}<div class="chart">{{range .Hourly}}<div class="bar" style="height:{{if .Flows}}{{.Flows}}{{else}}2{{end}}px" title="{{timeonly .Hour}} · {{.Flows}} flows"></div>{{end}}</div>{{else}}<div class="empty">No flow data yet. Access an audited NetBird resource to populate the chart.</div>{{end}}</section><section class="card section"><div class="section-head"><h2>Top Resources · 24h</h2><a class="muted" href="/access-logs">View all →</a></div>{{range .TopResources}}<div class="top-resource"><span>{{.Name}}</span><b>{{.Flows}}</b></div>{{else}}<div class="empty">No resource activity yet.</div>{{end}}</section></div><section class="card section"><div class="section-head"><h2>Recent Access Logs</h2><a class="muted" href="/access-logs">View all →</a></div>{{template "flowsTable" .}}</section><div class="layout"><section class="card section"><div class="section-head"><h2>Active VPN Sessions</h2><a class="muted" href="/vpn-sessions">View all →</a></div>{{template "sessionsTable" .}}</section><section class="card section"><div class="section-head"><h2>System Health</h2><a class="muted" href="/system-health">View all →</a></div><div class="statusline">Audit Server <span class="badge green"><span class="dot"></span>Running</span></div><div class="statusline" style="margin-top:12px">eBPF Sensor {{if .SensorOK}}<span class="badge green"><span class="dot"></span>Running</span>{{else}}<span class="badge red">No heartbeat</span>{{end}}</div><div class="statusline" style="margin-top:12px">NetBird Sync {{if .NetBirdOK}}<span class="badge green">Connected</span>{{else}}<span class="badge red">Stale</span>{{end}}</div></section></div>{{end}}
{{if eq .Page "logs"}}<div class="grid4"><div class="card metric"><div class="label">Total Accesses · 24h</div><div class="num">{{.Flows}}</div></div><div class="card metric"><div class="label">Active Flows</div><div class="num">{{.ActiveFlows}}</div></div><div class="card metric"><div class="label">Unique Users · 24h</div><div class="num">{{.UniqueUsers}}</div></div><div class="card metric"><div class="label">Audit Resources</div><div class="num">{{len .FilterResources}}</div></div></div><section class="card section"><form method="get" class="filters"><select class="select" name="period"><option value="1h" {{if eq .FilterPeriod "1h"}}selected{{end}}>Last hour</option><option value="24h" {{if eq .FilterPeriod "24h"}}selected{{end}}>Last 24 hours</option><option value="7d" {{if eq .FilterPeriod "7d"}}selected{{end}}>Last 7 days</option><option value="30d" {{if eq .FilterPeriod "30d"}}selected{{end}}>Last 30 days</option></select><select class="select" name="user"><option value="">All users</option>{{range .FilterUsers}}<option value="{{.}}">{{.}}</option>{{end}}</select><select class="select" name="resource"><option value="">All resources</option>{{range .FilterResources}}<option value="{{.}}">{{.}}</option>{{end}}</select><select class="select" name="protocol"><option value="">All protocols</option><option value="tcp">TCP</option><option value="udp">UDP</option></select><input class="input" name="q" value="{{.FilterQuery}}" placeholder="Search IP, device, resource..."><button class="btn primary">Apply</button><a class="btn" href="/access-logs">Reset</a><a class="btn" href="/export/flows.csv">Export CSV</a></form>{{template "flowsTable" .}}</section>{{end}}
{{if eq .Page "sessions"}}<section class="card section"><div class="section-head"><h2>VPN Session History</h2><span class="muted">NetBird API observed connect/disconnect events</span></div>{{template "sessionsTable" .}}</section>{{end}}
{{if eq .Page "resources"}}<div class="notice">Resources are synchronized from NetBird. The Audit Gateway never changes NetBird routing or policy; it only chooses which IP/CIDR resources are written to Access Logs.</div><section class="card section"><div class="section-head"><div><h2>NetBird Resources</h2><span class="muted">Last sync: {{timefmt .LastResourceSync}}</span></div><form method="post" action="/resources/sync"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="btn primary">↻ Sync Now</button></form></div>{{range .ResourceViews}}<div class="resource-row"><div class="resource-name"><b>{{.Name}}</b><small>{{.NetworkName}}</small></div><div>{{.Address}}<div class="muted" style="font-size:11px">{{.Type}}</div></div><div>{{if .Enabled}}<span class="badge green">NetBird Enabled</span>{{else}}<span class="badge gray">NetBird Disabled</span>{{end}}</div><div>{{if .AuditEnabled}}<span class="badge blue">Audited</span>{{else}}<span class="badge gray">Not audited</span>{{end}}</div><div>{{if not .Supported}}<span class="unsupported">Domain resources cannot be mapped by the IP flow sensor.</span>{{else if .AuditEnabled}}<form method="post" action="/resources/delete" class="inline-form"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.AuditID}}"><span class="muted">{{.AuditProtocol}} / {{.AuditPorts}}</span><button class="btn danger">Disable audit</button></form>{{else}}<form method="post" action="/resources/enable" class="inline-form"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="netbird_id" value="{{.ID}}"><select class="select" name="protocol"><option>tcp</option><option>udp</option></select><input class="input" name="ports" value="*" placeholder="443 or *"><button class="btn primary">Enable audit</button></form>{{end}}</div></div>{{else}}<div class="empty">No NetBird resources found. Create a Network Resource in NetBird, then click Sync Now.</div>{{end}}</section>{{end}}
{{if eq .Page "peers"}}<section class="card section"><div class="section-head"><h2>NetBird Peers</h2><span class="muted">Synchronized from /api/peers</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Status</th><th>User</th><th>Device</th><th>NetBird IP</th><th>Public IP</th><th>Last Seen</th></tr></thead><tbody>{{range .PeersList}}<tr><td>{{if .Connected}}<span class="badge green"><span class="dot"></span>Online</span>{{else}}<span class="badge gray">Offline</span>{{end}}</td><td>{{if .UserEmail}}{{.UserEmail}}{{else}}{{.UserName}}{{end}}</td><td>{{.Name}}</td><td>{{.IP}}</td><td>{{.PublicIP}}</td><td>{{timefmt .LastSeen}}</td></tr>{{end}}</tbody></table></div></section>{{end}}
{{if eq .Page "health"}}<div class="health-grid"><div class="card health"><div><b>Audit Server</b><div class="muted">Go HTTPS/API</div></div><span class="badge green"><span class="dot"></span>Running</span></div><div class="card health"><div><b>eBPF TCX Sensor</b><div class="muted">{{if .SensorInterface}}Attached to {{.SensorInterface}}{{else}}Waiting for heartbeat{{end}}</div></div>{{if .SensorOK}}<span class="badge green">Running</span>{{else}}<span class="badge red">Stale</span>{{end}}</div><div class="card health"><div><b>MySQL 8.4</b><div class="muted">Audit datastore</div></div>{{if .MySQLOK}}<span class="badge green">Healthy</span>{{else}}<span class="badge red">Unavailable</span>{{end}}</div><div class="card health"><div><b>NetBird API</b><div class="muted">Last sync {{timefmt .LastNetBirdSync}}</div></div>{{if .NetBirdOK}}<span class="badge green">Connected</span>{{else}}<span class="badge red">Stale</span>{{end}}</div></div>{{end}}
</main></div><div id="drawerOverlay" class="drawer-overlay"></div><aside id="flowDrawer" class="drawer"><div class="drawer-head"><div><h2 style="margin:0">Access Details</h2><span id="fd-status" class="muted">Observed</span></div><button id="closeDrawer" class="close">×</button></div><dl><dt>Time</dt><dd id="fd-time">-</dd><dt>User</dt><dd id="fd-user">-</dd><dt>Device</dt><dd id="fd-device">-</dd><dt>Source</dt><dd id="fd-source">-</dd><dt>Resource</dt><dd id="fd-resource">-</dd><dt>Destination</dt><dd id="fd-destination">-</dd><dt>Protocol</dt><dd id="fd-protocol">-</dd><dt>Traffic</dt><dd id="fd-traffic">-</dd><dt>Packets</dt><dd id="fd-packets">-</dd></dl></aside><script src="/assets/app.js" defer></script></body></html>
{{define "flowsTable"}}<div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Device</th><th>Source (NetBird IP)</th><th>Resource</th><th>Destination</th><th>Protocol</th><th>Traffic</th><th>Packets</th><th>Status</th></tr></thead><tbody>{{range .FlowsList}}<tr data-flow="1" data-time="{{timefmt .StartedAt}}" data-user="{{if .UserEmail}}{{.UserEmail}}{{else}}{{.UserName}}{{end}}" data-device="{{.PeerName}}" data-source="{{.SrcIP}}:{{.SrcPort}}" data-resource="{{.ResourceName}}" data-destination="{{.DstIP}}:{{.DstPort}}" data-protocol="{{.Protocol}}" data-traffic="{{bytesfmt (add .BytesTX .BytesRX)}}" data-packets="{{packets .PacketsTX .PacketsRX}}" data-status="{{if .Ended}}Ended{{else}}Active{{end}}"><td>{{timeonly .StartedAt}}</td><td>{{if .UserEmail}}{{.UserEmail}}{{else if .UserName}}{{.UserName}}{{else}}Unknown{{end}}</td><td>{{.PeerName}}</td><td>{{.SrcIP}}</td><td>{{.ResourceName}}</td><td>{{.DstIP}}:{{.DstPort}}</td><td><span class="badge blue">{{.Protocol}}</span></td><td>{{bytesfmt (add .BytesTX .BytesRX)}}</td><td>{{packets .PacketsTX .PacketsRX}}</td><td>{{if .Ended}}<span class="badge gray">Ended</span>{{else}}<span class="badge green"><span class="dot"></span>Active</span>{{end}}</td></tr>{{else}}<tr><td colspan="10"><div class="empty">No access logs recorded for this view.</div></td></tr>{{end}}</tbody></table></div>{{end}}
{{define "sessionsTable"}}<div class="table-wrap"><table class="table"><thead><tr><th>Connected</th><th>Disconnected</th><th>User</th><th>Device</th><th>NetBird IP</th><th>Public IP</th><th>Duration</th><th>Status</th></tr></thead><tbody>{{range .SessionsList}}<tr><td>{{timefmt .ConnectedAt}}</td><td>{{if .DisconnectedAt.Valid}}{{timefmt .DisconnectedAt.Time}}{{else}}—{{end}}</td><td>{{if .UserEmail}}{{.UserEmail}}{{else if .UserName}}{{.UserName}}{{else}}Unknown{{end}}</td><td>{{.PeerName}}</td><td>{{.PeerIP}}</td><td>{{.PublicIP}}</td><td>{{if .DisconnectedAt.Valid}}{{dur .ConnectedAt .DisconnectedAt.Time}}{{else}}{{dur .ConnectedAt (timeNow)}}{{end}}</td><td>{{if .DisconnectedAt.Valid}}<span class="badge gray">Offline</span>{{else}}<span class="badge green"><span class="dot"></span>Online</span>{{end}}</td></tr>{{else}}<tr><td colspan="8"><div class="empty">No VPN sessions recorded yet.</div></td></tr>{{end}}</tbody></table></div>{{end}}`
